# Os preços que já existem foram digitados à mão: ficam como manuais e o administrador
# os devolve ao automático pela tela Revisão de preços
def marcar_precos_existentes_como_manuais(apps, schema_editor):
    Produto = apps.get_model("cadastros", "Produto")
    Produto.objects.filter(preco_venda__gt=0).update(preco_manual=True)


# A nova permissão vai para os grupos que já cuidam de tudo em Cadastros
def liberar_revisao_de_precos(apps, schema_editor):
    app_config = apps.get_app_config("cadastros")
    app_config.models_module = True
    create_permissions(app_config, apps=apps, verbosity=0)
    app_config.models_module = None

    Group = apps.get_model("auth", "Group")
    Permission = apps.get_model("auth", "Permission")
    perm = Permission.objects.filter(content_type__app_label="cadastros", codename="revisar_precos").first()
    if perm:
        for grupo in Group.objects.filter(name__in=["Administrador", "Gerente"]):
            grupo.permissions.add(perm)


